insert into public.courses (id, language, dialect, title, description, cefr_level, goal_tag, position, published, school, prerequisite_ids)
values ('bbbb0004-0000-4000-8000-00000000002e', 'en', null, 'Oceanography', 'How the global ocean actually works -- the shape of the basins and the plate tectonics that build them, the chemistry of seawater, the currents and tides that move it, the ecosystems it supports, and the outsized role it plays in Earth''s carbon cycle and climate. You will read real profiles and time series and learn to reason with numbers, not just vocabulary. Structure adapted from OpenStax and OER Commons Earth-science materials (CC BY 4.0); all explanations original.', null, 'foundations', 44, true, 'science', '{}')
on conflict (id) do nothing;

insert into public.lessons (course_id, position, title, kind, body, grammar_notes_md, estimated_minutes)
select 'bbbb0004-0000-4000-8000-00000000002e', v.pos, v.title, v.kind, v.body::jsonb, v.notes, v.mins
from (values
  (1, 'Diagnostic: where are you now?', 'quiz', '{"questions":[{"prompt":"About what fraction of Earth''s surface is covered by ocean?","options":["about 30 percent","about 50 percent","about 71 percent","about 90 percent"],"answer":2,"explanation":"The ocean covers roughly 71 percent of the surface, with an average depth near 3,700 m -- see ''The ocean basins and plate tectonics''."},{"prompt":"The average salinity of seawater is closest to...","options":["3.5 g of salt per kg of seawater","35 g of salt per kg of seawater","350 g of salt per kg of seawater","0.35 g of salt per kg of seawater"],"answer":1,"explanation":"Average salinity is about 35 g/kg, often written 35 psu -- see ''Seawater chemistry and salinity''."},{"prompt":"New ocean floor is created at...","options":["deep-sea trenches","mid-ocean ridges","the centers of continents","coral reefs"],"answer":1,"explanation":"Seafloor spreading adds crust at mid-ocean ridges and destroys it at trenches -- see ''The ocean basins and plate tectonics''."},{"prompt":"In the Northern Hemisphere, the Coriolis effect deflects moving water to the...","options":["left","right","straight down","not at all"],"answer":1,"explanation":"Deflection is to the right in the north and to the left in the south, which sets the rotation of the gyres -- see ''Ocean circulation and currents''."},{"prompt":"Spring tides, the tides with the largest range, occur when...","options":["the Moon is at first quarter","the Sun and Moon pull at right angles","the Sun, Earth, and Moon are aligned","the Moon is farthest from Earth"],"answer":2,"explanation":"At new and full moon the Sun and Moon align and their pulls add -- see ''Waves and tides''."},{"prompt":"Roughly how much of the energy at one level of a marine food web passes to the next level up?","options":["about 1 percent","about 10 percent","about 50 percent","about 90 percent"],"answer":1,"explanation":"Only about 10 percent transfers per trophic step, so top predators are rare -- see ''Marine ecosystems and the food web''."},{"prompt":"Ocean acidification is caused mainly by the ocean absorbing...","options":["excess nitrogen","carbon dioxide from the atmosphere","plastic waste","extra sunlight"],"answer":1,"explanation":"Dissolved CO2 forms carbonic acid, lowering pH -- see ''Human impact: plastics and acidification''."},{"prompt":"The ocean''s role in climate is large mostly because water has a very high...","options":["transparency","heat capacity","salinity","electrical resistance"],"answer":1,"explanation":"Water''s high heat capacity lets the ocean store and move enormous amounts of heat -- see ''The carbon cycle and the ocean''s climate role''."}]}'::jsonb, null, 10),
  (2, 'The ocean basins and plate tectonics', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Describe the main features of an ocean basin and use a spreading rate to estimate the age and width of new seafloor. Warm-up: from the diagnostic, where is brand-new ocean crust made?"},{"heading":"The idea","text":"The ocean covers about 71 percent of Earth''s surface and averages roughly 3,700 m deep, dropping to about 10,935 m at Challenger Deep in the Mariana Trench. A basin has a shallow continental shelf near land, a steep continental slope, a broad flat abyssal plain, a central mid-ocean ridge, and deep trenches at its edges. Plate tectonics builds this shape: at a mid-ocean ridge, magma rises and hardens into new crust that spreads outward at a few centimeters per year, and at a trench old crust dives back into the mantle in a process called subduction. Because crust moves away from the ridge at a steady rate, its age increases with distance -- the youngest rock is at the ridge and the oldest sits near the continents."},{"heading":"Worked examples","text":"Suppose the Mid-Atlantic Ridge spreads at 2.5 cm per year on each side. Over 10 million years each side gains 2.5 cm/yr * 10,000,000 yr = 25,000,000 cm = 250 km of new floor, so the ocean widens by about 500 km total. To find the age of crust 1,000 km from the ridge, convert distance to centimeters: 1,000 km = 100,000,000 cm. Dividing by the 2.5 cm/yr half-rate gives 100,000,000 / 2.5 = 40,000,000 years, so that crust is about 40 million years old. Depth check: if the shelf edge sits at 150 m and the abyssal plain at 4,000 m, the slope between them drops 4,000 - 150 = 3,850 m."},{"heading":"Your turn","text":"1) At a spreading half-rate of 5 cm/yr, how wide a strip of new crust forms on one side in 2 million years, in km? 2) How old is crust 600 km from a ridge that spreads 3 cm/yr per side? 3) If average depth is 3,700 m and the deepest trench is 10,935 m, how much deeper is the trench than average? 4) Name the flat, deep feature that makes up most of a basin floor. 5) Which is older, crust at the ridge crest or crust near a continent? Answers: 1) 5 cm/yr * 2,000,000 yr = 10,000,000 cm = 100 km. 2) 600 km = 60,000,000 cm; 60,000,000 / 3 = 20,000,000 years, so about 20 million years. 3) 10,935 - 3,700 = 7,235 m. 4) the abyssal plain. 5) crust near a continent is older, because it has traveled farthest from the ridge."},{"heading":"Common mistakes & exit ticket","text":"Mistake: mixing up units -- always convert km to cm before dividing by a rate in cm/yr. Mistake: thinking the whole basin widens at the half-rate; each side gains the half-rate, so the total widening is twice that. Exit: (a) Where is the youngest ocean crust found? (b) What is subduction? Answers: at the mid-ocean ridge crest; the sinking of old ocean crust back into the mantle at a trench."}]}'::jsonb, 'Crust is created at mid-ocean ridges and consumed at trenches; the seafloor gets older the farther you travel from a ridge.', 14),
  (3, 'Seawater chemistry and salinity', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Convert between salinity and dissolved-salt mass, and explain why the proportions of the major ions stay constant. Warm-up: how many grams of salt are in 1 kg of average seawater?"},{"heading":"The idea","text":"Seawater is water with dissolved salts. Its salinity averages about 35 g of salt per kg of seawater, written 35 psu or 3.5 percent by mass. Six ions make up over 99 percent of that salt, led by chloride (about 55 percent of the salt mass) and sodium (about 31 percent). A key rule, the principle of constant proportions, says these major ions keep the same ratios everywhere, even where total salinity changes -- so measuring one, such as chloride, lets you infer the rest. Salinity rises where evaporation removes fresh water (warm subtropical seas) and falls where rain or rivers add it (near the equator and river mouths). Higher salinity and lower temperature both make seawater denser, and density differences drive deep circulation."},{"heading":"Worked examples","text":"How much salt is dissolved in 2 kg of average seawater at 35 g/kg? Multiply: 35 g/kg * 2 kg = 70 g of salt. If you fully evaporate a 500 g sample of 35 psu seawater, the salt left behind is 35 g/kg * 0.5 kg = 17.5 g. Now suppose a coastal sample reads only 28 psu because a river has diluted it; its salt content per kg is 28 g, which is 35 - 28 = 7 g/kg less than the open ocean. Using constant proportions, if chloride is about 55 percent of the salt, a 35 g/kg sample carries roughly 0.55 * 35 = 19.25 g of chloride per kg."},{"heading":"Your turn","text":"1) How many grams of salt are in 4 kg of 35 psu seawater? 2) A sample is 20 psu; what fraction, in percent by mass, is salt? 3) Evaporating 250 g of 36 psu seawater leaves how much salt? 4) Which is denser, cold salty water or warm fresh water? 5) If chloride is about 55 percent of the salt in a 30 g/kg sample, how many grams of chloride is that per kg? Answers: 1) 35 * 4 = 140 g. 2) 20 g/kg = 2.0 percent. 3) 36 g/kg * 0.25 kg = 9 g. 4) cold salty water is denser. 5) 0.55 * 30 = 16.5 g."},{"heading":"Common mistakes & exit ticket","text":"Mistake: reading 35 psu as 35 percent -- it is 3.5 percent, since 35 out of 1,000. Mistake: assuming ion ratios change with salinity; the total changes but the proportions stay fixed. Exit: (a) What does a salinity of 35 g/kg mean in percent by mass? (b) Name the two most abundant ions in seawater. Answers: 3.5 percent; chloride and sodium."}]}'::jsonb, 'Salinity is a mass ratio: grams of dissolved salt per kilogram of seawater. 35 g/kg means 35 parts salt in 1,000 parts seawater, that is 3.5 percent by mass.', 13),
  (4, 'Ocean circulation and currents', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain what drives surface and deep currents and compute transport and travel distances. Warm-up: which way does the Coriolis effect bend moving water in the Northern Hemisphere?"},{"heading":"The idea","text":"Two systems move ocean water. Wind-driven surface currents ride the prevailing winds, and Earth''s rotation adds the Coriolis effect, deflecting flow to the right in the Northern Hemisphere and to the left in the Southern. The result is a set of large circular gyres, one in each ocean basin, that carry warm water poleward on their western edges (like the Gulf Stream) and cool water back toward the equator. Beneath them, thermohaline circulation is driven by density: near the poles, cold, salty water grows dense and sinks, then creeps along the deep sea and slowly rises elsewhere, a global loop that takes on the order of 1,000 years to complete. Volume transport is measured in sverdrups, where 1 Sv = 1,000,000 cubic meters per second."},{"heading":"Worked examples","text":"The Gulf Stream carries roughly 30 Sv near Florida, which is 30 * 1,000,000 = 30,000,000 cubic meters of water per second. The Amazon River, the largest river on Earth, discharges only about 0.2 Sv, so the Gulf Stream moves about 30 / 0.2 = 150 times as much water. How far does a 2 m/s current push a drifting buoy in one day? There are 86,400 seconds in a day, so distance = 2 m/s * 86,400 s = 172,800 m = about 173 km. If deep water takes 1,000 years to circle the globe and travels 40,000 km, its average speed is 40,000 km / 1,000 yr = 40 km per year -- far slower than a surface current."},{"heading":"Your turn","text":"1) Convert 90 Sv to cubic meters per second. 2) A current flows at 1.5 m/s; how far does it carry a float in one day, in km? 3) If the Gulf Stream is 30 Sv and a smaller current is 6 Sv, how many times larger is the Gulf Stream? 4) Which way does the Coriolis effect deflect flow in the Southern Hemisphere? 5) What density conditions make surface water sink in the polar sea? Answers: 1) 90 * 1,000,000 = 90,000,000 cubic meters per second. 2) 1.5 * 86,400 = 129,600 m = 129.6 km. 3) 30 / 6 = 5 times. 4) to the left. 5) cold and salty, hence dense, water sinks."},{"heading":"Common mistakes & exit ticket","text":"Mistake: forgetting there are 86,400 seconds in a day when turning a speed into a daily distance. Mistake: thinking deep and surface currents share one driver -- wind drives the surface, density drives the deep. Exit: (a) What is 1 Sv in cubic meters per second? (b) Name the two properties that set seawater density in thermohaline circulation. Answers: 1,000,000 cubic meters per second; temperature and salinity."}]}'::jsonb, 'Surface currents are driven mainly by wind and steered by the Coriolis effect; deep currents are driven by density differences from temperature and salinity (thermohaline circulation).', 14),
  (5, 'Waves and tides', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Compute deep-water wave speed and wavelength from a period, and explain the spring and neap tidal cycle. Warm-up: when in the lunar month do the largest tides occur?"},{"heading":"The idea","text":"A wave carries energy, not water, across the sea surface; the water itself mostly circles in place. Wind waves are described by their period T, the time between passing crests. In deep water the speed is c = 1.56 * T meters per second and the wavelength is L = c * T = 1.56 * T * T meters, so longer-period swells travel faster and stretch farther apart. Tides are the slow rise and fall driven by the gravity of the Moon and Sun. Most coasts see a semidiurnal tide, two highs and two lows in about 24 hours 50 minutes, so successive high tides are roughly 12 hours 25 minutes apart. When the Sun, Earth, and Moon align at new and full moon, their pulls add to give large-range spring tides; when they sit at right angles at the quarter moons, the pulls partly cancel to give small-range neap tides."},{"heading":"Worked examples","text":"For a swell with period T = 10 s, the deep-water speed is c = 1.56 * 10 = 15.6 m/s and the wavelength is L = 1.56 * 10 * 10 = 156 m. For a shorter wind wave with T = 8 s, c = 1.56 * 8 = 12.48 m/s and L = 1.56 * 8 * 8 = 99.84 m, roughly 100 m. Tidal range is the height difference between high and low water: if high tide reaches 4.8 m on a tide gauge and the following low falls to 0.6 m, the range is 4.8 - 0.6 = 4.2 m. Timing: if a high tide occurs at 3:00, the next semidiurnal high is about 12 hours 25 minutes later, near 15:25."},{"heading":"Your turn","text":"1) Find the deep-water speed of a wave with period 12 s. 2) Find its wavelength. 3) High tide is 5.5 m and low tide is 1.1 m; what is the tidal range? 4) Do spring tides happen at new and full moon or at the quarter moons? 5) About how long after one high tide does the next semidiurnal high arrive? Answers: 1) c = 1.56 * 12 = 18.72 m/s. 2) L = 1.56 * 12 * 12 = 224.64 m. 3) 5.5 - 1.1 = 4.4 m. 4) at new and full moon. 5) about 12 hours 25 minutes."},{"heading":"Common mistakes & exit ticket","text":"Mistake: squaring the wrong quantity -- wavelength uses T * T, but speed uses T only. Mistake: swapping spring and neap; spring tides are the big ones at alignment, neap tides the small ones at right angles. Exit: (a) Write the deep-water speed formula. (b) When do neap tides occur? Answers: c = 1.56 * T; at the first- and third-quarter moons, when the Sun and Moon pull at right angles."}]}'::jsonb, 'A wave''s period T (seconds between crests) sets its speed and length in deep water: speed c = 1.56 * T (m/s) and wavelength L = 1.56 * T * T (m).', 13),
  (6, 'Checkpoint 1', 'quiz', '{"questions":[{"prompt":"A ridge spreads at 4 cm/yr per side. How old is crust 800 km from the ridge?","options":["about 10 million years","about 20 million years","about 40 million years","about 80 million years"],"answer":1,"explanation":"800 km = 80,000,000 cm; 80,000,000 / 4 = 20,000,000 years."},{"prompt":"How many grams of salt are dissolved in 3 kg of average (35 psu) seawater?","options":["35 g","70 g","105 g","350 g"],"answer":2,"explanation":"35 g/kg * 3 kg = 105 g."},{"prompt":"One sverdrup (1 Sv) equals...","options":["1,000 cubic meters per second","100,000 cubic meters per second","1,000,000 cubic meters per second","1,000,000,000 cubic meters per second"],"answer":2,"explanation":"1 Sv = 1,000,000 cubic meters per second, the standard unit of ocean transport."},{"prompt":"A deep-water wave has period 5 s. Its speed is closest to...","options":["3.1 m/s","7.8 m/s","15.6 m/s","25 m/s"],"answer":1,"explanation":"c = 1.56 * 5 = 7.8 m/s."},{"prompt":"In the Northern Hemisphere the Coriolis effect deflects moving water to the...","options":["left","right","equator","seafloor"],"answer":1,"explanation":"Deflection is to the right in the north, which sets clockwise gyres."},{"prompt":"Spring tides, with the largest range, happen when the Sun, Earth, and Moon are...","options":["at right angles","aligned","at their farthest apart","at the equinox only"],"answer":1,"explanation":"Alignment at new and full moon makes the solar and lunar pulls add."}]}'::jsonb, null, 8),
  (7, 'Marine ecosystems and the food web', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Trace energy through a marine food web and use the 10 percent rule to compute how much production a top predator requires. Warm-up: roughly what fraction of energy moves from one level to the next?"},{"heading":"The idea","text":"Sunlight powers the sea only in the top layer, the photic zone, which reaches down to about 200 m where enough light remains for photosynthesis. There, drifting phytoplankton act as primary producers, converting sunlight and dissolved nutrients into living matter. They are eaten by zooplankton, which are eaten by small fish, which feed larger fish and marine mammals. Each of these steps is a trophic level, and roughly 90 percent of the energy at one level is lost to movement, heat, and waste, so only about 10 percent reaches the next. This is why each level up has far less total mass and why top predators such as tuna and sharks are relatively rare. Nutrients returned by decomposers and delivered by upwelling refresh the producers and keep the web running."},{"heading":"Worked examples","text":"Start with 10,000 units of energy captured by phytoplankton. At 10 percent per step, zooplankton receive 1,000, small fish receive 100, and a tuna at the fourth level receives 10 units -- a 1,000-fold drop over three transfers. Turn that around: to add 1 kg of tuna body mass at trophic level 4, three transfers at 10 percent each mean you need 10 * 10 * 10 = 1,000 kg of phytoplankton production at the base. If instead the top predator sits at level 5, that is four transfers, so 10 * 10 * 10 * 10 = 10,000 kg of producers per kg of predator. A shorter web is far more efficient at feeding people."},{"heading":"Your turn","text":"1) With 10 percent transfer, how much of 5,000 units at the base reaches the third level? 2) How many kg of phytoplankton support 2 kg of a level-4 predator? 3) Down to about what depth does the photic zone extend? 4) What organisms are the ocean''s main primary producers? 5) Why are top predators rare compared with plankton? Answers: 1) 5,000 -> 500 -> 50, so 50 units at the third level. 2) 1,000 kg per kg, so 2 * 1,000 = 2,000 kg. 3) about 200 m. 4) phytoplankton. 5) because about 90 percent of energy is lost at each step, so little reaches the top."},{"heading":"Common mistakes & exit ticket","text":"Mistake: counting levels instead of transfers -- going from level 1 to level 4 is three steps, not four. Mistake: assuming most energy passes upward; it is about 10 percent, with 90 percent lost. Exit: (a) What is the 10 percent rule? (b) How many kg of producers support 1 kg of a level-4 predator? Answers: only about 10 percent of energy transfers between trophic levels; about 1,000 kg."}]}'::jsonb, 'Energy flows one way and shrinks at each step: only about 10 percent passes from one trophic level to the next, so it takes about 10 units of prey to build 1 unit of predator.', 13),
  (8, 'Coastal processes', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain longshore drift and use a simple sediment budget to predict whether a beach grows or shrinks. Warm-up: what happens to sand when waves strike a beach at an angle rather than head-on?"},{"heading":"The idea","text":"The coast is where wave energy reshapes the land. When waves approach at an angle, each one washes sand up the beach at that slant (the swash) and gravity pulls it straight back down (the backwash), so grains zigzag along the shore in a steady flow called longshore drift. A beach behaves like a bank account: it has inputs (sand from rivers, cliffs, and drift arriving from up-current) and outputs (drift leaving down-current, plus losses offshore). If inputs equal outputs, the beach holds steady; if outputs exceed inputs, it erodes. Hard structures change the balance: a groyne built across the drift traps sand on its up-current side and starves the beach just down-current. Soft cliffs retreat as waves undercut them, often at a fairly steady yearly rate."},{"heading":"Worked examples","text":"Suppose longshore drift carries 120,000 cubic meters of sand past a headland each year, and rivers add another 30,000 cubic meters, so inputs total 150,000. If drift leaving the far end removes 170,000 cubic meters per year, the budget is 150,000 - 170,000 = -20,000 cubic meters per year, a deficit, so the beach loses about 20,000 cubic meters annually and shrinks. Cliff retreat: if a soft cliff erodes 0.8 m per year, then over 25 years it retreats 0.8 * 25 = 20 m, so a house set 15 m back would be at the edge in 15 / 0.8 = about 19 years. A groyne that traps 5,000 cubic meters per year builds a wider up-current beach while the down-current beach loses the same 5,000."},{"heading":"Your turn","text":"1) Inputs to a beach are 90,000 cubic meters/yr and outputs are 90,000; is it growing, shrinking, or stable? 2) Inputs 60,000 and outputs 75,000 -- what is the yearly budget? 3) A cliff retreats 1.2 m/yr; how far in 30 years? 4) A cottage sits 24 m from a cliff edge retreating 1.5 m/yr; in about how many years is it reached? 5) Which side of a groyne collects sand? Answers: 1) inputs equal outputs, so it is stable. 2) 60,000 - 75,000 = -15,000 cubic meters/yr, a deficit. 3) 1.2 * 30 = 36 m. 4) 24 / 1.5 = 16 years. 5) the up-current side, where drift is blocked."},{"heading":"Common mistakes & exit ticket","text":"Mistake: thinking a groyne adds sand to the whole coast; it only redistributes it, starving the down-current beach. Mistake: ignoring inputs and outputs both -- erosion is about the balance, not just the waves. Exit: (a) What is longshore drift? (b) A beach with inputs below outputs will do what? Answers: the movement of sand along the shore by angled waves; it will erode."}]}'::jsonb, 'Waves hitting the shore at an angle move sand along the coast; this longshore drift is like a river of sand, and a beach stays stable only when sand in balances sand out.', 13),
  (9, 'The carbon cycle and the ocean''s climate role', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Describe how the ocean stores carbon and heat and compute how much carbon dioxide it removes from the air each year. Warm-up: why does water make the ocean such a powerful heat buffer?"},{"heading":"The idea","text":"The ocean holds far more carbon than the air -- roughly 38,000 gigatonnes of carbon in the sea versus about 870 gigatonnes in the atmosphere. Two pumps move carbon downward. The solubility pump dissolves carbon dioxide into cold surface water, which then sinks in the polar regions and carries the carbon into the deep sea. The biological pump works through life: phytoplankton fix carbon dioxide into their bodies by photosynthesis, and when they and the creatures that eat them die, some of that carbon sinks and is stored below. On top of this, water''s very high heat capacity lets the ocean absorb over 90 percent of the extra heat from a warming climate, which slows surface warming but raises sea level as the water expands and adds heat that stresses ecosystems."},{"heading":"Worked examples","text":"Humans emit about 36 gigatonnes of carbon dioxide per year. If the ocean absorbs about 25 percent of that, it removes 0.25 * 36 = 9 gigatonnes of carbon dioxide per year. Compare reservoirs: with about 38,000 gigatonnes of carbon in the ocean and about 870 in the air, the ocean holds 38,000 / 870 = about 44 times as much carbon. Thermal expansion and sea level: if global sea level rises 3.3 mm per year, then over 20 years it rises 3.3 * 20 = 66 mm, and over a century 3.3 * 100 = 330 mm, about 33 cm. Heat sharing: if the climate system gains 100 units of extra heat and the ocean takes over 90, then less than 10 remain for the land, ice, and air combined."},{"heading":"Your turn","text":"1) If emissions are 40 gigatonnes of carbon dioxide per year and the ocean absorbs 25 percent, how much does it take up? 2) At 3.3 mm/yr, how much sea level rise in 50 years, in mm? 3) Convert that to cm. 4) About how many times more carbon is in the ocean than the atmosphere? 5) About what share of excess climate heat does the ocean absorb? Answers: 1) 0.25 * 40 = 10 gigatonnes per year. 2) 3.3 * 50 = 165 mm. 3) 165 mm = 16.5 cm. 4) about 44 times (38,000 / 870). 5) over 90 percent."},{"heading":"Common mistakes & exit ticket","text":"Mistake: assuming the atmosphere holds most of Earth''s carbon; the ocean holds far more. Mistake: forgetting that absorbed heat expands water, so heat uptake still raises sea level. Exit: (a) Name the ocean''s two carbon pumps. (b) Roughly what fraction of excess heat does the ocean take up? Answers: the solubility pump and the biological pump; over 90 percent."}]}'::jsonb, 'The ocean is Earth''s largest active carbon reservoir and heat store; it takes up roughly a quarter of human carbon dioxide emissions and over 90 percent of the extra heat trapped by greenhouse gases.', 15),
  (10, 'Checkpoint 2', 'quiz', '{"questions":[{"prompt":"Using the 10 percent rule, how much of 8,000 energy units at the base reaches the third trophic level?","options":["800 units","400 units","80 units","8 units"],"answer":2,"explanation":"8,000 -> 800 -> 80, so 80 units reach the third level."},{"prompt":"About how deep does the sunlit photic zone extend?","options":["about 20 m","about 200 m","about 2,000 m","about 4,000 m"],"answer":1,"explanation":"Enough light for photosynthesis reaches down to roughly 200 m."},{"prompt":"A beach has inputs of 100,000 and outputs of 130,000 cubic meters of sand per year. It will...","options":["grow by 30,000","stay stable","erode by 30,000","erode by 230,000"],"answer":2,"explanation":"Budget = 100,000 - 130,000 = -30,000 cubic meters/yr, so it erodes."},{"prompt":"A cliff retreats 1.5 m per year. How far does it retreat in 20 years?","options":["15 m","20 m","30 m","300 m"],"answer":2,"explanation":"1.5 * 20 = 30 m."},{"prompt":"If humans emit 36 gigatonnes of carbon dioxide per year and the ocean absorbs about 25 percent, the ocean takes up about...","options":["3.6 gigatonnes","9 gigatonnes","18 gigatonnes","36 gigatonnes"],"answer":1,"explanation":"0.25 * 36 = 9 gigatonnes per year."},{"prompt":"At 3.3 mm per year, sea level rise over one century is closest to...","options":["3.3 cm","33 cm","3.3 m","0.33 mm"],"answer":1,"explanation":"3.3 mm/yr * 100 yr = 330 mm = 33 cm."}]}'::jsonb, null, 8),
  (11, 'Marine resources', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain the main resources the ocean provides and use a simple stock model to judge whether a catch is sustainable. Warm-up: what happens to a fish stock if the yearly catch is bigger than the yearly growth?"},{"heading":"The idea","text":"The ocean supplies food, energy, minerals, and even fresh water. Wild fisheries land on the order of 90 million tonnes of fish a year, and farmed seafood (aquaculture) now adds a comparable amount. The seabed holds oil and gas, and the water column and coasts increasingly host offshore wind. Desalination turns seawater into drinking water where rain is scarce. The central challenge is that living resources renew only so fast. A fish stock grows fastest when it is near half its natural carrying capacity, and the catch that just matches this growth is the maximum sustainable yield. Take less and the stock rebuilds; take more and it shrinks year after year, which is overfishing and can collapse a fishery entirely."},{"heading":"Worked examples","text":"Suppose a cod stock grows by 20,000 tonnes this year through births minus natural deaths. If the fleet catches 15,000 tonnes, that is 5,000 tonnes below growth, so the stock rises by 20,000 - 15,000 = 5,000 tonnes and is being fished sustainably. If instead the fleet lands 26,000 tonnes, the stock falls by 26,000 - 20,000 = 6,000 tonnes, which is overfishing. A carrying-capacity example: if a stock''s carrying capacity is 200,000 tonnes and growth peaks near half of that, the most productive stock size is about 100,000 tonnes, and managers aim to hold the population near there for the largest steady catch. Desalination scale: a plant making 50,000 cubic meters of fresh water per day supplies 50,000,000 / 200 = 250,000 people at 200 liters each per day."},{"heading":"Your turn","text":"1) A stock grows 12,000 tonnes/yr and the catch is 9,000; sustainable or not, and by how much does the stock change? 2) Same growth, but catch is 15,000; what happens? 3) If carrying capacity is 300,000 tonnes, near what stock size is growth greatest? 4) Name two non-food resources the ocean provides. 5) What is the maximum sustainable yield? Answers: 1) sustainable; stock rises by 12,000 - 9,000 = 3,000 tonnes. 2) overfished; stock falls by 15,000 - 12,000 = 3,000 tonnes. 3) about 150,000 tonnes, roughly half of carrying capacity. 4) any two of offshore oil and gas, offshore wind energy, seabed minerals, fresh water from desalination. 5) the largest catch a stock can replace each year without shrinking."},{"heading":"Common mistakes & exit ticket","text":"Mistake: thinking a bigger catch is always better; beyond MSY the stock and future catches fall. Mistake: assuming growth is fastest when the stock is largest, when it actually peaks near half of carrying capacity. Exit: (a) When is a catch sustainable? (b) Near what fraction of carrying capacity does a stock grow fastest? Answers: when the catch is at or below the yearly growth; near one half."}]}'::jsonb, 'A fishery is sustainable only when the catch does not exceed the stock''s yearly growth; the maximum sustainable yield (MSY) is the largest catch a stock can replace year after year.', 13),
  (12, 'Human impact: plastics and acidification', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain how plastic and carbon dioxide harm the ocean and convert a pH change into a change in acidity. Warm-up: what does a pH drop of 0.1 mean for the number of hydrogen ions?"},{"heading":"The idea","text":"Two large-scale human impacts stand out. First, plastic: roughly 8 million tonnes of plastic enter the ocean each year, where sunlight and waves break it into microplastics that spread through the food web and persist for centuries. Second, acidification: the ocean absorbs about a quarter of human carbon dioxide, and dissolved carbon dioxide forms carbonic acid, which lowers pH. Because pH is a logarithmic scale, small-looking changes matter: each drop of 1.0 pH unit is a tenfold rise in hydrogen ions. Since the Industrial Revolution, surface ocean pH has fallen from about 8.2 to about 8.1. More acidic water makes it harder for corals, shellfish, and some plankton to build calcium carbonate shells and skeletons, threatening the base of many food webs."},{"heading":"Worked examples","text":"How much more acidic is water when pH falls from 8.2 to 8.1? The change is 0.1 unit, and the hydrogen-ion ratio is 10 raised to the 0.1 power, which is about 1.26 -- so there are about 26 percent more hydrogen ions. A full unit, say 8.1 down to 7.1, would be 10 raised to the 1.0 power = 10 times more. Plastic scale: if 8,000,000 tonnes enter the sea each year and one garbage truck holds about 8 tonnes, that is 8,000,000 / 8 = 1,000,000 truckloads a year, or about 1,000,000 / 365 = roughly 2,700 truckloads a day. Microplastic counting: if a net tows through water holding 3 particles per cubic meter and filters 500 cubic meters, it collects 3 * 500 = 1,500 particles."},{"heading":"Your turn","text":"1) A pH drop of 0.3 unit corresponds to 10 raised to the 0.3 power, about 2.0; how many times more hydrogen ions is that? 2) How many times more hydrogen ions for a drop of exactly 2.0 pH units? 3) At 3 particles per cubic meter, how many microplastics in 1,200 cubic meters of water? 4) If 8,000,000 tonnes of plastic enter per year, how many tonnes per day, to the nearest hundred? 5) Why does acidification threaten corals and shellfish? Answers: 1) about 2.0 times more. 2) 10 raised to the 2.0 power = 100 times more. 3) 3 * 1,200 = 3,600 particles. 4) 8,000,000 / 365 = about 21,900 tonnes per day. 5) it makes it harder to build calcium carbonate shells and skeletons."},{"heading":"Common mistakes & exit ticket","text":"Mistake: reading pH as a linear scale -- a change of 0.1 is not 0.1 percent but about 26 percent more hydrogen ions. Mistake: thinking microplastics disappear; they persist for centuries and spread through the web. Exit: (a) By roughly how much has surface ocean pH fallen since preindustrial times, and what does that mean for acidity? (b) What forms when carbon dioxide dissolves in seawater? Answers: about 0.1 unit, roughly 26 percent more hydrogen ions; carbonic acid."}]}'::jsonb, 'A drop in pH of 1 unit means 10 times more hydrogen ions; a drop of 0.1 unit means 10 raised to the 0.1 power, about 1.26 times more, that is roughly 26 percent more acidic.', 14),
  (13, 'Capstone: interpreting ocean data', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Read real oceanographic profiles and time series and pull rates, ranges, and trends out of the numbers. Warm-up: how do you turn a starting value and an ending value into a rate of change?"},{"heading":"The idea","text":"Oceanographers rarely see the whole ocean at once; they infer it from data. A depth profile plots a property against depth: a temperature profile usually shows a warm mixed layer on top, then a thermocline where temperature drops fast, then cold deep water. A time series plots a property against time and reveals trends, such as rising sea level or falling pH. Thousands of drifting Argo floats now sample temperature and salinity worldwide. The core skills are simple arithmetic: subtract to get a range or a difference, and divide a change by its time span to get a rate. Always carry units, and sanity-check whether the sign and size make physical sense."},{"heading":"Worked examples","text":"Temperature profile: surface 24 C at 0 m, 23 C at 50 m, then 12 C at 150 m and 6 C at 400 m. The steepest drop is between 50 m and 150 m, where temperature falls 23 - 12 = 11 C over 150 - 50 = 100 m, a gradient of 11 / 100 = 0.11 C per meter -- that band is the thermocline. Sea level time series: a gauge reads 12 mm above baseline in year 2000 and 78 mm in 2020. The rise is 78 - 12 = 66 mm over 2020 - 2000 = 20 years, so the rate is 66 / 20 = 3.3 mm per year. pH time series: 8.11 in 2005 and 8.05 in 2020 gives a change of 8.05 - 8.11 = -0.06 over 15 years, or -0.06 / 15 = -0.004 pH units per year, a clear acidifying trend. Salinity profile difference: 34.5 psu at the surface and 34.9 psu at 200 m differ by 34.9 - 34.5 = 0.4 psu."},{"heading":"Your turn","text":"Use this profile -- 0 m: 25 C; 40 m: 24 C; 120 m: 14 C; 300 m: 7 C -- and this sea level record: 5 mm in 1995, 95 mm in 2025. 1) Over which depth band is the thermocline, and what is its gradient in C per meter? 2) What is the total temperature drop from surface to 300 m? 3) What is the sea level rise rate in mm per year? 4) At that rate, how much rise over the next 40 years? 5) If pH goes from 8.10 to 8.04 over 12 years, what is the yearly change? Answers: 1) between 40 m and 120 m; (24 - 14) / (120 - 40) = 10 / 80 = 0.125 C per meter. 2) 25 - 7 = 18 C. 3) (95 - 5) / (2025 - 1995) = 90 / 30 = 3.0 mm per year. 4) 3.0 * 40 = 120 mm = 12 cm. 5) (8.04 - 8.10) / 12 = -0.06 / 12 = -0.005 pH units per year."},{"heading":"Common mistakes & exit ticket","text":"Mistake: dividing by the wrong time span -- use the elapsed time between the two readings, not one of the calendar years. Mistake: dropping the minus sign on a decreasing trend; a falling pH or temperature gives a negative rate. Exit: (a) How do you compute a rate from two data points? (b) In a temperature profile, what is the thermocline? Answers: (final minus initial) divided by elapsed time; the depth band where temperature falls most steeply between the warm mixed layer and the cold deep water."}]}'::jsonb, 'A rate is a change divided by the time over which it happened; read it straight off a data table by taking (final value minus initial value) divided by (elapsed time).', 16),
  (14, 'Final quiz', 'quiz', '{"questions":[{"prompt":"New ocean crust forms at mid-ocean ridges and is destroyed at trenches through...","options":["evaporation","subduction","longshore drift","photosynthesis"],"answer":1,"explanation":"Old crust sinks back into the mantle at trenches, a process called subduction."},{"prompt":"A salinity of 35 psu is the same as...","options":["35 percent salt by mass","3.5 percent salt by mass","0.35 percent salt by mass","350 percent salt by mass"],"answer":1,"explanation":"35 g per 1,000 g is 3.5 percent by mass."},{"prompt":"The Gulf Stream (about 30 Sv) carries how many cubic meters of water per second?","options":["30,000","300,000","3,000,000","30,000,000"],"answer":3,"explanation":"30 Sv * 1,000,000 = 30,000,000 cubic meters per second."},{"prompt":"A deep-water swell has period 10 s. Its wavelength is closest to...","options":["16 m","100 m","156 m","312 m"],"answer":2,"explanation":"L = 1.56 * 10 * 10 = 156 m."},{"prompt":"To build 1 kg of a level-4 predator, about how much phytoplankton production is needed under the 10 percent rule?","options":["10 kg","100 kg","1,000 kg","10,000 kg"],"answer":2,"explanation":"Three transfers at 10 percent each: 10 * 10 * 10 = 1,000 kg."},{"prompt":"A beach receives 80,000 cubic meters of sand per year and loses 95,000. It will...","options":["grow by 15,000","stay stable","erode by 15,000","erode by 175,000"],"answer":2,"explanation":"Budget = 80,000 - 95,000 = -15,000 cubic meters/yr, so it erodes."},{"prompt":"Compared with the atmosphere, the ocean stores roughly how much more carbon?","options":["about the same","about 4 times as much","about 44 times as much","about 4,400 times as much"],"answer":2,"explanation":"About 38,000 gigatonnes in the ocean versus about 870 in the air, roughly 44 times."},{"prompt":"Surface ocean pH has fallen from about 8.2 to about 8.1, which means hydrogen ions have increased by about...","options":["0.1 percent","1 percent","26 percent","100 percent"],"answer":2,"explanation":"10 raised to the 0.1 power is about 1.26, so about 26 percent more hydrogen ions."},{"prompt":"A tide gauge reads 10 mm in 2000 and 76 mm in 2020. The sea level rise rate is...","options":["1.3 mm/yr","3.3 mm/yr","6.6 mm/yr","66 mm/yr"],"answer":1,"explanation":"(76 - 10) / (2020 - 2000) = 66 / 20 = 3.3 mm per year."},{"prompt":"A fish stock grows 18,000 tonnes in a year and the catch is 22,000 tonnes. This is...","options":["sustainable, stock rises 4,000","sustainable, stock steady","overfishing, stock falls 4,000","overfishing, stock falls 40,000"],"answer":2,"explanation":"Catch exceeds growth by 22,000 - 18,000 = 4,000 tonnes, so the stock falls by 4,000 -- overfishing."}]}'::jsonb, null, 10)
) as v(pos, title, kind, body, notes, mins)
where not exists (
  select 1 from public.lessons l
  where l.course_id = 'bbbb0004-0000-4000-8000-00000000002e' and l.position = v.pos
);
